400	func deleteReactionsByCreatorTx(ctx context.Context, tx *sql.Tx, userID int32) error {
401		_, err := tx.ExecContext(ctx, `DELETE FROM reaction WHERE creator_id = `+deleteUserPlaceholder(1), userID)
402		return err
